import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as n,af as s}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const v=JSON.parse('{"title":"Gemini Canvas","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/canvas.md","filePath":"zh/products/ai-coding/gemini/canvas.md","lastUpdated":1780925587000}'),i={name:"zh/products/ai-coding/gemini/canvas.md"};function l(r,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="gemini-canvas" tabindex="-1">Gemini Canvas <a class="header-anchor" href="#gemini-canvas" aria-label="Permalink to &quot;Gemini Canvas&quot;">​</a></h1><blockquote><p>Gemini Canvas 提供了一个与传统聊天窗口并排的动态工作区，允许生成代码或复杂文档时进行细粒度的实时修改。</p></blockquote><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><p>Canvas 最具颠覆性的特性在于其<strong>生成式用户界面（Generative UI）</strong>。传统的 AI 助手大多只能在聊天框中输出静态的纯文本或 Markdown 格式的代码块。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><h3 id="generative-ui" tabindex="-1">Generative UI <a class="header-anchor" href="#generative-ui" aria-label="Permalink to &quot;Generative UI&quot;">​</a></h3><p>Gemini Canvas 能够利用后台<strong>原生代码执行和 WebGL 技术</strong>，直接在视图中渲染：</p><ul><li>动态布局</li><li>可点击的交互式图表</li><li>3D 模型</li></ul><p>当用户调整视图中的滑块或切换按钮时，界面能够<strong>实时响应更新</strong>。</p><h3 id="局部重绘" tabindex="-1">局部重绘 <a class="header-anchor" href="#局部重绘" aria-label="Permalink to &quot;局部重绘&quot;">​</a></h3><p>开发者可以高亮代码中的特定函数或 UI 组件的一小段 HTML/CSS，要求系统&quot;仅对选中的部分进行重构，优化动画过渡效果&quot;，而<strong>无需重新生成整个文件</strong>。</p><h2 id="极速原型流程" tabindex="-1">极速原型流程 <a class="header-anchor" href="#极速原型流程" aria-label="Permalink to &quot;极速原型流程&quot;">​</a></h2><h3 id="传统方式-vs-canvas-方式" tabindex="-1">传统方式 vs Canvas 方式 <a class="header-anchor" href="#传统方式-vs-canvas-方式" aria-label="Permalink to &quot;传统方式 vs Canvas 方式&quot;">​</a></h3><p><strong>传统方式</strong>（为非技术部门快速开发内部数据看板）：</p><ol><li>配置 React</li><li>引入图表库（D3.js 或 Recharts）</li><li>设置状态管理</li><li>编写 CSS</li></ol><p><strong>Canvas 方式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 输入提示词 → Canvas 渲染微应用</span></span>
<span class="line"><span>2. 审查交互逻辑 → 后续提示词精炼 UI</span></span>
<span class="line"><span>3. 复制代码片段 → 企业主代码库工程化封装</span></span></code></pre></div><h3 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据以下 JSON 结构，构建一个包含实时收入折线图和客户流失率饼图的自由职业者业务仪表盘，要求：</span></span>
<span class="line"><span>- 支持暗黑模式切换</span></span>
<span class="line"><span>- 使用 Recharts 库</span></span>
<span class="line"><span>- 响应式布局</span></span></code></pre></div><h2 id="分层渐进策略" tabindex="-1">分层渐进策略 <a class="header-anchor" href="#分层渐进策略" aria-label="Permalink to &quot;分层渐进策略&quot;">​</a></h2><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><p>一次性要求 Canvas 生成带有复杂业务逻辑的全尺寸应用。</p><h3 id="最佳实践-分层渐进" tabindex="-1">最佳实践：分层渐进 <a class="header-anchor" href="#最佳实践-分层渐进" aria-label="Permalink to &quot;最佳实践：分层渐进&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一层：DOM 结构 + 基础 JavaScript 交互</span></span>
<span class="line"><span>    ↓ 确认逻辑无误</span></span>
<span class="line"><span>第二层：应用企业设计系统（Tailwind CSS / CSS 变量）</span></span>
<span class="line"><span>    ↓ 保持代码整洁</span></span>
<span class="line"><span>第三层：工程化封装（TypeScript / 测试 / 文档）</span></span></code></pre></div><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th style="text-align:center;">ROI 评级</th><th>说明</th></tr></thead><tbody><tr><td>一次性原型设计</td><td style="text-align:center;">⭐⭐⭐</td><td>快速验证想法，无需投入工程化资源</td></tr><tr><td>内部工具快速孵化</td><td style="text-align:center;">⭐⭐⭐</td><td>为非技术部门快速开发小工具</td></tr><tr><td>微应用生成</td><td style="text-align:center;">⭐⭐</td><td>独立完整的轻量级应用</td></tr><tr><td>生产级应用</td><td style="text-align:center;">⭐</td><td>容错率低，不适合严谨的生产系统</td></tr></tbody></table><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://gemini.google/overview/canvas/" target="_blank" rel="noreferrer">Canvas 概览</a></li></ul>`,28)])])}const m=e(i,[["render",l]]);export{v as __pageData,m as default};
